#include <algorithm>
#include <gtest/gtest.h>

// Class under test: a tiny one-sided limit book
class Book {
public:
    void add(double px, int qty) {
        totalQty_ += qty;
        best_ = std::max(best_, px);
    }
    double best() const { return best_; }
    int totalQty() const { return totalQty_; }
private:
    double best_ = 0.0;
    int totalQty_ = 0;
};

class BookTest : public ::testing::Test {
protected:
    void SetUp() override {        // runs before EVERY test in this fixture
        book_.add(100.0, 10);      // shared starting state
    }
    Book book_;                    // constructed fresh per test
};

TEST_F(BookTest, TracksBestPrice) {
    book_.add(101.5, 5);
    EXPECT_DOUBLE_EQ(book_.best(), 101.5);   // exact-bit near-equality for doubles
    EXPECT_EQ(book_.totalQty(), 15);         // 10 (SetUp) + 5
}

TEST_F(BookTest, LowerAddLeavesBestUnchanged) {
    book_.add(99.0, 7);
    ASSERT_EQ(book_.totalQty(), 17);         // ASSERT: abort THIS test if wrong
    EXPECT_DOUBLE_EQ(book_.best(), 100.0);   // only reached if the assert held
}

