#include <gtest/gtest.h>
#include "pricer/pnl.hpp"

TEST(PnL, FlatPositionHasZeroPnL) {
    Position p{0, 0.0};
    EXPECT_DOUBLE_EQ(realised_pnl(p, 100.0), 0.0);
}

TEST(PnL, AverageCostUpdatesOnIncreasing) {
    Position p;
    p.apply_fill(+100, 50.0);
    p.apply_fill(+100, 60.0);
    EXPECT_DOUBLE_EQ(p.avg_cost, 55.0);      // weighted, not last-price
}

TEST(PnL, ReducingFlipRealisesCorrectly) {
    Position p;
    p.apply_fill(+100, 50.0);
    p.apply_fill(-150, 60.0);                // flip to short
    EXPECT_DOUBLE_EQ(p.realised, 1000.0);   // 100 * 10 profit
    EXPECT_EQ(p.qty, -50);
    EXPECT_DOUBLE_EQ(p.avg_cost, 60.0);      // new side priced at fill
}

TEST(PnL, NoFloatingDriftAcrossCycle) {
    Position p;
    for (int i = 0; i < 100000; ++i) p.apply_fill(+1, 0.1);
    EXPECT_NEAR(p.qty * p.avg_cost, 10000.0, 1e-6);   // accumulation sanity
}

